<div class="wrap">
  <header>
    <svg class="mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M6 8h12l-1.1 11a2 2 0 0 1-2 1.8H9.1a2 2 0 0 1-2-1.8L6 8Z"/>
      <path d="M9 8a3 3 0 0 1 6 0"/>
    </svg>
    <div>
      <h1>Bevásárlólista</h1>
      <p class="sub">Pipáld be, amit megvettél – a lista megmarad, ha bezárod az ablakot.</p>
    </div>
  </header>

  <form class="add-form" id="addForm" autocomplete="off">
    <label class="sr" for="nameInput">Új tétel</label>
    <input id="nameInput" type="text" placeholder="Mit veszel? Pl. paradicsom" maxlength="80">
    <label class="sr" for="catSelect">Kategória</label>
    <select id="catSelect">
      <option value="zoldseg">Zöldség</option>
      <option value="pekaru">Pékáru</option>
      <option value="tejtermekek">Tejtermék</option>
      <option value="egyeb">Egyéb</option>
    </select>
    <button type="submit" class="btn-primary">Hozzáad</button>
  </form>

  <div class="toolbar">
    <p class="status" id="status"></p>
    <div class="toolbar-actions">
      <button type="button" id="clearDone" class="btn-ghost">Készek törlése</button>
      <button type="button" id="clearAll" class="btn-danger">Lista törlése</button>
    </div>
  </div>
  <div class="progress" aria-hidden="true"><div class="progress-fill" id="progressFill" style="width:0%"></div></div>

  <div class="confirm" id="confirmBox" hidden>
    <p id="confirmMsg"></p>
    <span class="spacer"></span>
    <button type="button" id="confirmYes" class="btn-primary">Igen, töröljük</button>
    <button type="button" id="confirmNo" class="btn-ghost">Mégse</button>
  </div>

  <main>
    <div id="list"></div>
    <div class="empty" id="empty" hidden>
      <p class="big">A listád még üres</p>
      <p>Írd be fent az első tételt, és válassz hozzá egy kategóriát.</p>
    </div>
  </main>

  <p class="sr-only-live" id="live" role="status" aria-live="polite"></p>
