<script>
(function(){
  'use strict';

  var KEY = 'shopping-list-v1';
  var CATEGORIES = [
    {id:'zoldseg', name:'Zöldség'},
    {id:'pekaru', name:'Pékáru'},
    {id:'tejtermekek', name:'Tejtermék'},
    {id:'egyeb', name:'Egyéb'}
  ];

  var items = [];
  var pending = null;

  var listEl = document.getElementById('list');
  var emptyEl = document.getElementById('empty');
  var statusEl = document.getElementById('status');
  var fillEl = document.getElementById('progressFill');
  var liveEl = document.getElementById('live');
  var confirmBox = document.getElementById('confirmBox');
  var confirmMsg = document.getElementById('confirmMsg');
  var addForm = document.getElementById('addForm');
  var nameInput = document.getElementById('nameInput');
  var catSelect = document.getElementById('catSelect');
  var clearDoneBtn = document.getElementById('clearDone');
  var clearAllBtn = document.getElementById('clearAll');

  function uid(){ return Date.now().toString(36) + Math.random().toString(36).slice(2,7); }

  function catName(id){
    for (var i=0;i<CATEGORIES.length;i++){ if (CATEGORIES[i].id===id) return CATEGORIES[i].name; }
    return 'Egyéb';
  }

  function save(){
    if (window.alfy && window.alfy.storage && window.alfy.storage.set){
      try { window.alfy.storage.set(KEY, items); } catch(e){}
    }
  }

  function announce(msg){ liveEl.textContent = msg; }

  function render(){
    listEl.innerHTML = '';
    var total = items.length;
    var done = 0, i;
    for (i=0;i<items.length;i++){ if (items[i].done) done++; }

    if (total === 0){
      emptyEl.hidden = false;
      statusEl.textContent = 'Nincs tétel a listán';
      fillEl.style.width = '0%';
      clearDoneBtn.disabled = true;
      clearAllBtn.disabled = true;
      return;
    }

    emptyEl.hidden = true;
    clearAllBtn.disabled = false;
    clearDoneBtn.disabled = (done === 0);
    fillEl.style.width = Math.round(done/total*100) + '%';
    statusEl.textContent = done + ' / ' + total + ' megvéve';

    for (var c=0;c<CATEGORIES.length;c++){
      var cat = CATEGORIES[c];
      var group = items.filter(function(it){ return it.category === cat.id; });
      if (!group.length) continue;

      var section = document.createElement('section');
      section.className = 'cat';

      var head = document.createElement('div');
      head.className = 'cat-head';
      var h2 = document.createElement('h2');
      var dot = document.createElement('span');
      dot.className = 'dot';
      h2.appendChild(dot);
      h2.appendChild(document.createTextNode(cat.name));
      var count = document.createElement('span');
      count.className = 'cat-count';
      var gDone = group.filter(function(it){ return it.done; }).length;
      count.textContent = gDone + ' / ' + group.length;
      head.appendChild(h2);
      head.appendChild(count);
      section.appendChild(head);

      var ul = document.createElement('ul');
      for (var j=0;j<group.length;j++){
        ul.appendChild(buildItem(group[j]));
      }
      section.appendChild(ul);
      listEl.appendChild(section);
    }
  }

  function buildItem(item){
    var li = document.createElement('li');
    li.className = 'item' + (item.done ? ' done' : '');
    li.dataset.id = item.id;

    var label = document.createElement('label');
    label.className = 'check';

    var input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = !!item.done;
    input.setAttribute('aria-label', item.name + (item.done ? ' – megvéve' : ''));
    input.addEventListener('change', function(){
      item.done = input.checked;
      save();
      render();
      announce(item.name + (item.done ? ' megjelölve megvettnek.' : ' ismét felkerült a listára.'));
    });

    var box = document.createElement('span');
    box.className = 'box';
    box.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7"/></svg>';

    label.appendChild(input);
    label.appendChild(box);

    var text = document.createElement('span');
    text.className = 'label';
    text.textContent = item.name;

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'del';
    del.textContent = '\u00d7';
    del.setAttribute('aria-label', 'Törlés: ' + item.name);
    del.addEventListener('click', function(){
      items = items.filter(function(it){ return it.id !== item.id; });
      save();
      render();
      announce(item.name + ' törölve.');
    });

    li.appendChild(label);
    li.appendChild(text);
    li.appendChild(del);
    return li;
  }

  function closeConfirm(){ pending = null; confirmBox.hidden = true; }

  addForm.addEventListener('submit', function(e){
    e.preventDefault();
    var name = nameInput.value.trim();
    if (!name){
      nameInput.focus();
      announce('Írd be, mit szeretnél hozzáadni.');
      return;
    }
    items.push({ id: uid(), name: name, category: catSelect.value, done: false });
    save();
    render();
    nameInput.value = '';
    nameInput.focus();
    announce(name + ' hozzáadva a(z) ' + catName(catSelect.value) + ' kategóriához.');
  });

  clearDoneBtn.addEventListener('click', function(){
    var n = items.filter(function(it){ return it.done; }).length;
    if (!n) return;
    items = items.filter(function(it){ return !it.done; });
    save();
    render();
    announce(n + ' kész tétel törölve.');
  });

  clearAllBtn.addEventListener('click', function(){
    if (!items.length) return;
    pending = 'all';
    confirmMsg.textContent = 'Biztosan törölni szeretnéd az egész listát?';
    confirmBox.hidden = false;
    document.getElementById('confirmYes').focus();
  });

  document.getElementById('confirmYes').addEventListener('click', function(){
    if (pending === 'all'){
      items = [];
      save();
      render();
      announce('A lista törölve.');
    }
    closeConfirm();
    clearAllBtn.focus();
  });

  document.getElementById('confirmNo').addEventListener('click', function(){
    var wasAll = pending === 'all';
    closeConfirm();
    if (wasAll) clearAllBtn.focus();
  });

  function load(){
    if (window.alfy && window.alfy.storage && window.alfy.storage.get){
      try {
        window.alfy.storage.get(KEY).then(function(v){
          if (Array.isArray(v)) items = v;
          render();
        }).catch(function(){ render(); });
      } catch(e){ render(); }
    } else {
      render();
    }
  }

  load();
})();
</script>
</body>
</html>
